import { Charge, filterCharges } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function expectError(action: () => void, ctor: typeof Error, message: string): void {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof ctor, message);
}

const charges: Charge[] = [
  { id: "c1", accountId: "a", day: "2024-02-28", amount: 0 },
  { id: "c2", accountId: "b", day: "2024-02-29", amount: 5 },
  { id: "c3", accountId: "a", day: "2024-02-29", amount: 10.5 },
  { id: "c4", accountId: "a", day: "2024-03-01", amount: 20 },
  { id: "c5", accountId: "a", day: "2024-03-02", amount: 30 }
];
const before = charges.map((charge) => ({ ...charge }));
const result = filterCharges(charges, "a", "2024-02-29", "2024-03-01");
assert(result.length === 2 && result[0].id === "c3" && result[1].id === "c4", "filter is exact, inclusive, and ordered");
assert(result[0] !== charges[2] && result[1] !== charges[3], "matching records are fresh copies");
result[0].amount = 999;
assert(charges[2].amount === 10.5, "results do not alias input records");
assert(charges.every((charge, index) => charge.id === before[index].id && charge.accountId === before[index].accountId && charge.day === before[index].day && charge.amount === before[index].amount), "input is not mutated");
assert(filterCharges(charges, "missing", "2024-01-01", "2024-12-31").length === 0, "no matches returns an empty array");
assert(filterCharges([], "a", "2000-02-29", "2000-02-29").length === 0, "empty input and leap-day boundary are valid");

expectError(() => filterCharges(charges, "a", "2024-03-02", "2024-03-01"), RangeError, "reversed range throws RangeError");
for (const badDay of ["2024-2-01", "2024-02-30", "1900-02-29", "2024-13-01", "2024-01-00", "abcd-ef-gh"] ) {
  expectError(() => filterCharges([], "a", badDay, "2024-12-31"), TypeError, `invalid fromDay ${badDay}`);
  expectError(() => filterCharges([], "a", "2024-01-01", badDay), TypeError, `invalid toDay ${badDay}`);
}
expectError(() => filterCharges([], "", "2024-01-01", "2024-01-01"), TypeError, "empty account argument throws TypeError");
expectError(() => filterCharges([], 4 as unknown as string, "2024-01-01", "2024-01-01"), TypeError, "non-string account argument throws TypeError");

const malformed: unknown[] = [
  null,
  { id: "", accountId: "a", day: "2024-01-01", amount: 1 },
  { id: "x", accountId: "", day: "2024-01-01", amount: 1 },
  { id: "x", accountId: "a", day: "2023-02-29", amount: 1 },
  { id: "x", accountId: "a", day: "2024-01-01", amount: -1 },
  { id: "x", accountId: "a", day: "2024-01-01", amount: Number.NaN },
  { id: "x", accountId: "a", day: "2024-01-01", amount: Number.POSITIVE_INFINITY }
];
for (const bad of malformed) {
  expectError(() => filterCharges([bad as Charge], "a", "2024-01-01", "2024-12-31"), TypeError, "malformed records throw TypeError");
}
expectError(() => filterCharges([
  { id: "valid", accountId: "a", day: "2024-01-01", amount: 1 },
  { id: "bad", accountId: "other", day: "2024-02-30", amount: 1 }
], "a", "2024-01-01", "2024-12-31"), TypeError, "nonmatching records are still validated");

